import { Digest, JsonSchema, type RecordCodec, SemVer, TextId } from "../core";
import { PackageId, PackagePin } from "../definition-references";
import { ContributionAttribution } from "./attribution";
import type { FacetData } from "./data";
import {
    DataRecordCodec,
    compareText,
    requireArray,
    requireDataObject,
    requireExactFields,
    requireNonblank,
    requireSchemaDocument,
    requireString
} from "./data";
import { FacetPackageId, FacetRef, SlotName } from "./id";

export class SlotAuthorityPolicy {
    public readonly contribute: readonly string[];
    public readonly visibility: readonly string[];

    public constructor(contribute: readonly string[], visibility: readonly string[]) {
        this.contribute = canonicalSelectors(contribute, "Slot contribute authority");
        this.visibility = canonicalSelectors(visibility, "Slot visibility authority");
        Object.freeze(this);
    }

    public static fromData(payload: FacetData): SlotAuthorityPolicy {
        const object = requireDataObject(payload, "Slot authority policy");
        requireExactFields(object, ["contribute", "visibility"]);
        return new SlotAuthorityPolicy(
            requireArray(object["contribute"], "Slot contribute authority").map((value) =>
                requireString(value, "Slot contribute selector")
            ),
            requireArray(object["visibility"], "Slot visibility authority").map((value) =>
                requireString(value, "Slot visibility selector")
            )
        );
    }

    public static encode(policy: SlotAuthorityPolicy): Uint8Array {
        return slotAuthorityPolicyCodec.encode(policy);
    }

    public static decode(bytes: Uint8Array): SlotAuthorityPolicy {
        return slotAuthorityPolicyCodec.decode(bytes);
    }

    public toData(): FacetData {
        return { contribute: this.contribute, visibility: this.visibility };
    }
}

const slotAuthorityPolicyCodec = new DataRecordCodec(
    [SlotAuthorityPolicy],
    "facet.slot-authority-policy",
    (policy: SlotAuthorityPolicy) => policy.toData(),
    (payload) => SlotAuthorityPolicy.fromData(payload)
);

export class SlotDeclaration {
    public constructor(
        public readonly name: SlotName,
        public readonly entrySchema: JsonSchema,
        public readonly authority: SlotAuthorityPolicy
    ) {
        Object.freeze(this);
    }

    public static fromData(payload: FacetData): SlotDeclaration {
        const object = requireDataObject(payload, "Slot declaration");
        requireExactFields(object, ["authority", "entrySchema", "name"]);
        return new SlotDeclaration(
            new SlotName(requireString(object["name"], "Slot name")),
            new JsonSchema(requireSchemaDocument(object["entrySchema"], "Slot entry schema")),
            SlotAuthorityPolicy.fromData(object["authority"]!)
        );
    }

    public static encode(slot: SlotDeclaration): Uint8Array {
        return slotDeclarationCodec.encode(slot);
    }

    public static decode(bytes: Uint8Array): SlotDeclaration {
        return slotDeclarationCodec.decode(bytes);
    }

    public toData(): FacetData {
        return {
            authority: this.authority.toData(),
            entrySchema: this.entrySchema.document,
            name: this.name.value
        };
    }
}

const slotDeclarationCodec = new DataRecordCodec(
    [SlotDeclaration, SlotAuthorityPolicy, TextId, JsonSchema, SlotName],
    "facet.slot-declaration",
    (slot: SlotDeclaration) => slot.toData(),
    (payload) => SlotDeclaration.fromData(payload)
);

/**
 * A Slot declaration as a Scope holds it: the manifest's declaration plus the §4.2
 * attribution of the Facet whose `slots` contribution materialized it. The manifest half
 * is authored before a release exists, so the pin lives here rather than on
 * `SlotDeclaration`, and an installed Slot the host cannot attribute cannot be built.
 */
export class InstalledSlot {
    public constructor(
        public readonly declaration: SlotDeclaration,
        public readonly attribution: ContributionAttribution
    ) {
        if (
            !(declaration instanceof SlotDeclaration) ||
            !(attribution instanceof ContributionAttribution)
        ) {
            throw new TypeError("An installed Slot carries its declaration and its attribution");
        }
        Object.freeze(this);
    }

    public static fromData(payload: FacetData): InstalledSlot {
        const object = requireDataObject(payload, "Installed Slot");
        requireExactFields(object, ["contributor", "declaration", "package"]);
        const declaration = object["declaration"];
        if (declaration === undefined) {
            throw new TypeError("Installed Slot carries no Slot declaration");
        }
        return new InstalledSlot(
            SlotDeclaration.fromData(declaration),
            ContributionAttribution.decodeFields(object, "Installed Slot")
        );
    }

    /**
     * The record's own codec, so a reader that must declare the kinds it can decode names
     * this one from the record rather than restating its version (§8.3).
     */
    public static get codec(): RecordCodec<InstalledSlot> {
        return installedSlotCodec;
    }

    public static encode(slot: InstalledSlot): Uint8Array {
        return installedSlotCodec.encode(slot);
    }

    public static decode(bytes: Uint8Array): InstalledSlot {
        return installedSlotCodec.decode(bytes);
    }

    public toData(): FacetData {
        return { ...this.attribution.encodeFields(), declaration: this.declaration.toData() };
    }
}

const installedSlotCodec = new DataRecordCodec(
    [
        InstalledSlot,
        SlotDeclaration,
        ContributionAttribution,
        SlotAuthorityPolicy,
        TextId,
        JsonSchema,
        SlotName,
        FacetRef,
        FacetPackageId,
        Digest,
        SemVer,
        PackageId,
        PackagePin
    ],
    "facet.installed-slot",
    (slot: InstalledSlot) => slot.toData(),
    (payload) => InstalledSlot.fromData(payload)
);

function canonicalSelectors(values: readonly string[], subject: string): readonly string[] {
    if (values.length === 0) {
        throw new TypeError(`${subject} must not be empty`);
    }
    for (const value of values) {
        requireNonblank(value, `${subject} selector`);
    }
    const ordered = [...values].sort(compareText);
    if (new Set(ordered).size !== ordered.length) {
        throw new TypeError(`${subject} selectors must be unique`);
    }
    return Object.freeze(ordered);
}
